  1→'use client';
  2→
  3→import { cn } from '@tpmjs/utils/cn';
  4→import { forwardRef } from 'react';
  5→import type {
  6→  SkeletonAvatarProps,
  7→  SkeletonCardProps,
  8→  SkeletonProps,
  9→  SkeletonTextProps,
 10→} from './types';
 11→import {
 12→  skeletonAvatarVariants,
 13→  skeletonCardImageVariants,
 14→  skeletonCardVariants,
 15→  skeletonTextContainerVariants,
 16→  skeletonVariants,
 17→} from './variants';
 18→
 19→/**
 20→ * Normalize dimension to CSS value
 21→ */
 22→function normalizeDimension(value: string | number | undefined): string | undefined {
 23→  if (value === undefined) return undefined;
 24→  return typeof value === 'number' ? `${value}px` : value;
 25→}
 26→
 27→/**
 28→ * Skeleton component
 29→ *
 30→ * A placeholder component for loading states.
 31→ *
 32→ * @example
 33→ * ```tsx
 34→ * import { Skeleton } from '@tpmjs/ui/Skeleton/Skeleton';
 35→ *
 36→ * function MyComponent() {
 37→ *   return (
 38→ *     <div>
 39→ *       <Skeleton variant="text" width="60%" />
 40→ *       <Skeleton variant="text" width="80%" />
 41→ *       <Skeleton variant="circular" width={40} height={40} />
 42→ *       <Skeleton variant="rectangular" width="100%" height={200} />
 43→ *     </div>
 44→ *   );
 45→ * }
 46→ * ```
 47→ */
 48→export const Skeleton = forwardRef<HTMLDivElement, SkeletonProps>(
 49→  (
 50→    {
 51→      variant = 'text',
 52→      animation = 'pulse',
 53→      width,
 54→      height,
 55→      lines = 1,
 56→      gap = '0.5rem',
 57→      lastLineShort = false,
 58→      className,
 59→      style,
 60→      ...props
 61→    },
 62→    ref
 63→  ) => {
 64→    // Handle multiple lines for text variant
 65→    if (variant === 'text' && lines > 1) {
 66→      const gapValue = normalizeDimension(gap);
 67→
 68→      return (
 69→        <div
 70→          ref={ref}
 71→          className={cn(skeletonTextContainerVariants({}), className)}
 72→          style={{ gap: gapValue, ...style }}
 73→          {...props}
 74→        >
 75→          {Array.from({ length: lines }).map((_, index) => {
 76→            const isLast = index === lines - 1;
 77→            const lineWidth = isLast && lastLineShort ? '60%' : width || '100%';
 78→
 79→            return (
 80→              <div
 81→                key={index}
 82→                className={skeletonVariants({ variant, animation })}
 83→                style={{
 84→                  width: normalizeDimension(lineWidth),
 85→                  height: normalizeDimension(height),
 86→                }}
 87→              />
 88→            );
 89→          })}
 90→        </div>
 91→      );
 92→    }
 93→
 94→    return (
 95→      <div
 96→        ref={ref}
 97→        className={cn(skeletonVariants({ variant, animation }), className)}
 98→        style={{
 99→          width: normalizeDimension(width),
100→          height: normalizeDimension(height),
101→          ...style,
102→        }}
103→        {...props}
104→      />
105→    );
106→  }
107→);
108→
109→Skeleton.displayName = 'Skeleton';
110→
111→/**
112→ * SkeletonText component
113→ *
114→ * A preset for text loading placeholders.
115→ *
116→ * @example
117→ * ```tsx
118→ * import { SkeletonText } from '@tpmjs/ui/Skeleton/Skeleton';
119→ *
120→ * function MyComponent() {
121→ *   return <SkeletonText lines={3} />;
122→ * }
123→ * ```
124→ */
125→export const SkeletonText = forwardRef<HTMLDivElement, SkeletonTextProps>(
126→  ({ lines = 3, gap = '0.5rem', width, animation = 'pulse', className, style, ...props }, ref) => {
127→    const gapValue = normalizeDimension(gap);
128→    const widths = Array.isArray(width) ? width : undefined;
129→
130→    return (
131→      <div
132→        ref={ref}
133→        className={cn(skeletonTextContainerVariants({}), className)}
134→        style={{ gap: gapValue, ...style }}
135→        {...props}
136→      >
137→        {Array.from({ length: lines }).map((_, index) => {
138→          let lineWidth: string | number = '100%';
139→
140→          if (widths && widths[index] !== undefined) {
141→            lineWidth = widths[index];
142→          } else if (!Array.isArray(width) && width !== undefined) {
143→            lineWidth = width;
144→          } else if (index === lines - 1) {
145→            // Make last line shorter by default
146→            lineWidth = '60%';
147→          }
148→
149→          return (
150→            <div
151→              key={index}
152→              className={skeletonVariants({ variant: 'text', animation })}
153→              style={{ width: normalizeDimension(lineWidth) }}
154→            />
155→          );
156→        })}
157→      </div>
158→    );
159→  }
160→);
161→
162→SkeletonText.displayName = 'SkeletonText';
163→
164→/**
165→ * SkeletonAvatar component
166→ *
167→ * A preset for avatar loading placeholders.
168→ *
169→ * @example
170→ * ```tsx
171→ * import { SkeletonAvatar } from '@tpmjs/ui/Skeleton/Skeleton';
172→ *
173→ * function MyComponent() {
174→ *   return <SkeletonAvatar size="lg" />;
175→ * }
176→ * ```
177→ */
178→export const SkeletonAvatar = forwardRef<HTMLDivElement, SkeletonAvatarProps>(
179→  ({ size = 'md', animation = 'pulse', className, ...props }, ref) => (
180→    <div
181→      ref={ref}
182→      className={cn(skeletonAvatarVariants({ size, animation }), className)}
183→      {...props}
184→    />
185→  )
186→);
187→
188→SkeletonAvatar.displayName = 'SkeletonAvatar';
189→
190→/**
191→ * SkeletonCard component
192→ *
193→ * A preset for card loading placeholders.
194→ *
195→ * @example
196→ * ```tsx
197→ * import { SkeletonCard } from '@tpmjs/ui/Skeleton/Skeleton';
198→ *
199→ * function MyComponent() {
200→ *   return <SkeletonCard showImage lines={3} />;
201→ * }
202→ * ```
203→ */
204→export const SkeletonCard = forwardRef<HTMLDivElement, SkeletonCardProps>(
205→  ({ showImage = true, lines = 3, animation = 'pulse', className, ...props }, ref) => (
206→    <div ref={ref} className={cn(skeletonCardVariants({}), className)} {...props}>
207→      {showImage && <div className={skeletonCardImageVariants({ animation })} />}
208→      <div className="space-y-2">
209→        {/* Title skeleton */}
210→        <div
211→          className={skeletonVariants({ variant: 'text', animation })}
212→          style={{ width: '70%', height: '1.25rem' }}
213→        />
214→        {/* Content skeletons */}
215→        {Array.from({ length: lines }).map((_, index) => (
216→          <div
217→            key={index}
218→            className={skeletonVariants({ variant: 'text', animation })}
219→            style={{
220→              width: index === lines - 1 ? '50%' : '100%',
221→            }}
222→          />
223→        ))}
224→      </div>
225→    </div>
226→  )
227→);
228→
229→SkeletonCard.displayName = 'SkeletonCard';
230→
231→/**
232→ * SkeletonTable component
233→ *
234→ * A preset for table loading placeholders.
235→ *
236→ * @example
237→ * ```tsx
238→ * import { SkeletonTable } from '@tpmjs/ui/Skeleton/Skeleton';
239→ *
240→ * function MyComponent() {
241→ *   return <SkeletonTable rows={5} columns={4} />;
242→ * }
243→ * ```
244→ */
245→export interface SkeletonTableProps extends React.HTMLAttributes<HTMLDivElement> {
246→  rows?: number;
247→  columns?: number;
248→  animation?: 'pulse' | 'wave' | 'none';
249→}
250→
251→export const SkeletonTable = forwardRef<HTMLDivElement, SkeletonTableProps>(
252→  ({ rows = 5, columns = 4, animation = 'pulse', className, ...props }, ref) => (
253→    <div ref={ref} className={cn('w-full', className)} {...props}>
254→      {/* Header */}
255→      <div className="flex gap-4 py-3 border-b border-border">
256→        {Array.from({ length: columns }).map((_, colIndex) => (
257→          <div
258→            key={`header-${colIndex}`}
259→            className={cn(skeletonVariants({ variant: 'text', animation }), 'flex-1')}
260→            style={{ height: '1rem' }}
261→          />
262→        ))}
263→      </div>
264→      {/* Rows */}
265→      {Array.from({ length: rows }).map((_, rowIndex) => (
266→        <div
267→          key={`row-${rowIndex}`}
268→          className="flex gap-4 py-3 border-b border-border last:border-b-0"
269→        >
270→          {Array.from({ length: columns }).map((_, colIndex) => (
271→            <div
272→              key={`cell-${rowIndex}-${colIndex}`}
273→              className={cn(skeletonVariants({ variant: 'text', animation }), 'flex-1')}
274→              style={{ height: '1rem' }}
275→            />
276→          ))}
277→        </div>
278→      ))}
279→    </div>
280→  )
281→);
282→
283→SkeletonTable.displayName = 'SkeletonTable';
