246→export default function AgentChatPage(): React.ReactElement {
247→  const params = useParams();
248→  const router = useRouter();
249→  const agentId = params.id as string;
250→  const chatId = params.chatId as string;
251→
252→  const [agent, setAgent] = useState<Agent | null>(null);
253→  const [conversations, setConversations] = useState<Conversation[]>([]);
254→  const activeConversationId = chatId;
255→  const [messages, setMessages] = useState<Message[]>([]);
256→  const [input, setInput] = useState('');
257→  const [isLoading, setIsLoading] = useState(true);
258→  const [isSending, setIsSending] = useState(false);
259→  const [streamingContent, setStreamingContent] = useState('');
260→  const [error, setError] = useState<string | null>(null);
261→  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
262→  const [expandedToolCalls, setExpandedToolCalls] = useState<Set<string>>(new Set());
263→
264→  // UI state
265→  const [showToolsPanel, setShowToolsPanel] = useState(true);
266→  const [showSettings, setShowSettings] = useState(false);
267→  const [selectedTool, setSelectedTool] = useState<ToolInfo | null>(null);
268→
269→  const messagesEndRef = useRef<HTMLDivElement>(null);
270→  const inputRef = useRef<HTMLTextAreaElement>(null);
271→
272→  const toggleToolCall = (toolCallId: string) => {
273→    setExpandedToolCalls((prev) => {
274→      const next = new Set(prev);
275→      if (next.has(toolCallId)) {
276→        next.delete(toolCallId);
277→      } else {
278→        next.add(toolCallId);
279→      }
280→      return next;
281→    });
282→  };
283→
284→  // Fetch agent data
285→  const fetchAgent = useCallback(async () => {
286→    try {
287→      const response = await fetch(`/api/agents/${agentId}`);
288→      const data = await response.json();
289→
290→      if (data.success) {
291→        setAgent(data.data);
292→      } else {
293→        if (response.status === 401) {
294→          router.push('/sign-in');
295→          return;
296→        }
297→        setError(data.error || 'Failed to fetch agent');
298→      }
299→    } catch (err) {
300→      console.error('Failed to fetch agent:', err);
301→      setError('Failed to fetch agent');
302→    }
303→  }, [agentId, router]);
304→
305→  // Fetch conversations
306→  const fetchConversations = useCallback(async () => {
307→    if (!agent) return;
308→
309→    try {
310→      const response = await fetch(`/api/agents/${agentId}/conversations`);
311→      const data = await response.json();
312→
313→      if (data.success) {
314→        setConversations(data.data);
315→      }
316→    } catch (err) {
317→      console.error('Failed to fetch conversations:', err);
318→    }
319→  }, [agent, agentId]);
320→
321→  // Fetch messages for active conversation
322→  const fetchMessages = useCallback(async () => {
323→    if (!agent || !activeConversationId) return;
324→
325→    try {
326→      const response = await fetch(`/api/agents/${agentId}/conversation/${activeConversationId}`);
327→      const data = await response.json();
328→
329→      if (data.success) {
330→        const msgs = data.data.messages || [];
331→        setMessages(msgs);
332→      }
333→    } catch (err) {
334→      console.error('Failed to fetch messages:', err);
335→    }
336→  }, [agent, agentId, activeConversationId]);
337→
338→  useEffect(() => {
339→    const init = async () => {
340→      await fetchAgent();
341→      setIsLoading(false);
342→    };
343→    init();
344→  }, [fetchAgent]);
345→
346→  useEffect(() => {
347→    if (agent) {
348→      fetchConversations();
349→    }
350→  }, [agent, fetchConversations]);
351→
352→  useEffect(() => {
353→    if (activeConversationId) {
354→      fetchMessages();
355→    } else {
356→      setMessages([]);
357→    }
358→  }, [activeConversationId, fetchMessages]);
359→
360→  // Scroll to bottom only when messages change or streaming content updates
361→  useEffect(() => {
362→    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
363→  }, []);
364→
365→  const handleSelectConversation = (convSlug: string) => {
366→    router.push(`/dashboard/agents/${agentId}/chat/${convSlug}`);
367→  };
368→
369→  const handleSend = async () => {
370→    if (!input.trim() || !agent || isSending) return;
371→
372→    const messageContent = input.trim();
373→    setInput('');
374→    setIsSending(true);
375→    setStreamingContent('');
376→    setError(null);
377→    setToolCalls([]);
378→
379→    const conversationId = activeConversationId || chatId;
380→
381→    // Optimistically add user message
382→    const userMessage: Message = {
383→      id: `temp-${Date.now()}`,
384→      role: 'USER',
385→      content: messageContent,
386→      createdAt: new Date().toISOString(),
387→    };
388→    setMessages((prev) => [...prev, userMessage]);
389→
390→    try {
391→      const response = await fetch(`/api/agents/${agentId}/conversation/${conversationId}`, {
392→        method: 'POST',
393→        headers: { 'Content-Type': 'application/json' },
394→        body: JSON.stringify({ message: messageContent }),
395→      });
396→
397→      if (!response.ok) {
398→        const errorData = await response.json();
399→        throw new Error(errorData.error || 'Failed to send message');
400→      }
401→
402→      // Handle SSE stream
403→      const reader = response.body?.getReader();
404→      if (!reader) throw new Error('No response body');
405→
406→      const decoder = new TextDecoder();
407→      let buffer = '';
408→
409→      while (true) {
410→        const { done, value } = await reader.read();
411→        if (done) break;
412→
413→        buffer += decoder.decode(value, { stream: true });
414→
415→        // Parse SSE events
416→        const lines = buffer.split('\n');
417→        buffer = lines.pop() || '';
418→
419→        let eventType = '';
420→        for (const line of lines) {
421→          if (line.startsWith('event: ')) {
422→            eventType = line.slice(7);
423→          } else if (line.startsWith('data: ')) {
424→            const data = JSON.parse(line.slice(6));
425→
426→            switch (eventType) {
427→              case 'chunk':
428→                setStreamingContent((prev) => prev + data.text);
429→                break;
430→              case 'tool_call':
431→                setToolCalls((prev) => [
432→                  ...prev,
433→                  {
434→                    toolCallId: data.toolCallId,
435→                    toolName: data.toolName,
436→                    input: data.input,
437→                    status: 'running',
438→                  },
439→                ]);
440→                setExpandedToolCalls((prev) => new Set([...prev, data.toolCallId]));
441→                break;
442→              case 'tool_result':
443→                setToolCalls((prev) =>
444→                  prev.map((tc) =>
445→                    tc.toolCallId === data.toolCallId
446→                      ? { ...tc, output: data.output, status: 'success' as const }
447→                      : tc
448→                  )
449→                );
450→                break;
451→              case 'complete':
452→                await fetchMessages();
453→                await fetchConversations();
454→                setStreamingContent('');
455→                setToolCalls([]);
456→                break;
457→              case 'error':
458→                throw new Error(data.message);
459→            }
460→          }
461→        }
462→      }
463→    } catch (err) {
464→      console.error('Failed to send message:', err);
465→      setError(err instanceof Error ? err.message : 'Failed to send message');
466→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
467→    } finally {
468→      setIsSending(false);
469→      setStreamingContent('');
470→      inputRef.current?.focus();
471→    }
472→  };
473→
474→  const handleKeyDown = (e: React.KeyboardEvent) => {
475→    if (e.key === 'Enter' && !e.shiftKey) {
476→      e.preventDefault();
477→      handleSend();
478→    }
479→  };
480→
481→  const startNewConversation = () => {
482→    const newId = generateConversationId();
483→    router.push(`/dashboard/agents/${agentId}/chat/${newId}`);
484→  };
485→
486→  const handleSettingsChange = (newSettings: AgentSettings) => {
487→    if (agent) {
488→      setAgent({
489→        ...agent,
490→        ...newSettings,
491→      });
492→    }
493→  };
494→
495→  if (isLoading) {
496→    return (
497→      <DashboardLayout
498→        title="Loading..."
499→        showBackButton
500→        backUrl={`/dashboard/agents/${agentId}`}
501→        fullHeight
502→      >
503→        <div className="flex items-center justify-center h-full">
504→          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
505→        </div>
506→      </DashboardLayout>
507→    );
508→  }
509→
510→  if (error && !agent) {
511→    return (
512→      <DashboardLayout title="Error" showBackButton backUrl="/dashboard/agents" fullHeight>
513→        <div className="flex items-center justify-center h-full">
514→          <div className="text-center">
515→            <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
516→            <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
517→            <p className="text-foreground-secondary mb-4">{error}</p>
518→            <Link href="/dashboard/agents">
519→              <Button>Back to Agents</Button>
520→            </Link>
521→          </div>
522→        </div>
523→      </DashboardLayout>
524→    );
525→  }
526→
527→  if (!agent) {
528→    return (
529→      <DashboardLayout
530→        title="Loading..."
531→        showBackButton
532→        backUrl={`/dashboard/agents/${agentId}`}
533→        fullHeight
534→      >
535→        <div className="flex items-center justify-center h-full">
536→          <Icon icon="loader" size="lg" className="animate-spin text-foreground-secondary" />
537→        </div>
538→      </DashboardLayout>
539→    );
540→  }
541→
542→  return (
543→    <DashboardLayout
544→      title={agent.name}
545→      subtitle={`${PROVIDER_DISPLAY_NAMES[agent.provider]} / ${agent.modelId}`}
546→      showBackButton
547→      backUrl={`/dashboard/agents/${agent.id}`}
548→      fullHeight
549→      actions={
550→        <div className="flex items-center gap-2">
551→          <Button
552→            variant="ghost"
553→            size="sm"
554→            onClick={() => setShowToolsPanel(!showToolsPanel)}
555→            title={showToolsPanel ? 'Hide tools panel' : 'Show tools panel'}
556→            className={showToolsPanel ? 'bg-primary/10 text-primary' : ''}
557→          >
558→            <Icon icon="puzzle" size="xs" className="mr-1.5" />
559→            <span className="hidden sm:inline">Tools</span>
560→            {agent.tools.length > 0 && (
561→              <Badge variant="secondary" className="ml-1.5 text-[10px]">
562→                {agent.tools.length}
563→              </Badge>
564→            )}
565→          </Button>
566→          <Button
567→            variant="ghost"
568→            size="sm"
569→            onClick={() => setShowSettings(true)}
570→            title="Agent settings"
571→          >
572→            <Icon icon="edit" size="xs" className="mr-1.5" />
573→            <span className="hidden sm:inline">Settings</span>
574→          </Button>
575→          <Button
576→            variant="ghost"
577→            size="sm"
578→            onClick={() => {
579→              window.open(
580→                `/api/agents/${agentId}/conversation/${activeConversationId}?format=json`,
581→                '_blank'
582→              );
583→            }}
584→            title="View conversation as JSON"
585→          >
586→            <Icon icon="terminal" size="xs" />
587→          </Button>
588→          <Button variant="outline" size="sm" onClick={startNewConversation}>
589→            <Icon icon="plus" size="xs" className="mr-1.5" />
590→            New Chat
591→          </Button>
592→        </div>
593→      }
594→    >
595→      <div className="flex h-full overflow-hidden">
596→        {/* Conversations Sidebar */}
597→        <div className="w-56 border-r border-dashed border-border flex flex-col bg-surface hidden md:flex">
598→          <div className="p-3 border-b border-dashed border-border">
599→            <span className="font-mono text-xs text-foreground-tertiary lowercase">
600→              conversations
601→            </span>
602→          </div>
603→          <div className="flex-1 overflow-y-auto p-2">
604→            {conversations.length === 0 ? (
605→              <p className="text-xs text-foreground-tertiary text-center py-4 font-mono">
606→                no conversations yet
607→              </p>
