779→              <p className="text-sm text-error font-mono">{error}</p>
780→            </div>
781→          )}
782→
783→          {/* Input Area */}
784→          <div className="border-t border-dashed border-border p-4 bg-surface">
785→            <div className="flex items-end gap-2">
786→              <Textarea
787→                ref={inputRef}
788→                value={input}
789→                onChange={(e) => setInput(e.target.value)}
790→                onKeyDown={handleKeyDown}
791→                placeholder="Type a message..."
792→                rows={1}
793→                resize="none"
794→                className="flex-1 min-h-[48px] max-h-[200px] font-mono"
795→                style={{
796→                  height: 'auto',
797→                  minHeight: '48px',
798→                }}
799→                onInput={(e) => {
800→                  const target = e.target as HTMLTextAreaElement;
801→                  target.style.height = 'auto';
802→                  target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
803→                }}
804→              />
805→              <Button onClick={handleSend} disabled={isSending || !input.trim()}>
806→                <Icon icon="send" size="sm" />
807→              </Button>
808→            </div>
809→            <p className="text-[10px] text-foreground-tertiary mt-2 font-mono">
810→              enter to send, shift+enter for new line
811→            </p>
812→          </div>
813→        </div>
814→
815→        {/* Tools Panel */}
816→        <ChatToolsPanel
817→          tools={agent.tools}
818→          collections={agent.collections}
819→          isOpen={showToolsPanel}
820→          onClose={() => setShowToolsPanel(false)}
821→          onToolClick={setSelectedTool}
822→        />
823→      </div>
824→
825→      {/* Tool Details Modal */}
826→      <ToolDetailsModal
827→        tool={selectedTool}
828→        open={!!selectedTool}
